#!/usr/bin/env node
// Build the glossaries. Each repo gets repos/<name>/GLOSSARY.md from its domain graph alone. The
// estate glossary GLOSSARY.md merges the terms of all repos. It also has one entry for each shared
// resource of shared-resources.json: the name and a link to its section of docs/shared-resources.md.
// A regenerated domain graph or a changed resource needs only a rerun.
// Usage: node build-glossary.mjs           write the glossaries
//        node build-glossary.mjs --check   exit 1 if a glossary is missing or stale (CI)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { SHARED_RESOURCES_DATA, SHARED_RESOURCES_PAGE, isText, loadEstate, parseJson, readDocsFile, readSharedResources, root } from "./estate.mjs";
import { slugger } from "./slug.mjs";

const SCRIPT = ".github/scripts/build-glossary.mjs";
const check = process.argv.includes("--check");
const { repos, count, errors } = loadEstate();

// Text from the graph goes into Markdown: escape what would change its meaning.
const md = (s) => s.trim().replace(/[\\`*[\]<>]/g, "\\$&").replace(/(^|[^\p{L}\p{N}])_|_(?=[^\p{L}\p{N}]|$)/gu, (m) => m.replace("_", "\\_"));
const code = (s) => (s.includes("`") ? md(s) : `\`${s.trim()}\``);
const byName = (a, b) => a.localeCompare(b, "en", { sensitivity: "base" }) || a.localeCompare(b, "en");

// Read one domain graph: its domains (name, summary, terms, rules, flows) in graph order.
function readGraph(name) {
  const at = `repos/${name}/domain-graph.json`;
  const graph = readDocsFile(at, errors, parseJson);
  if (graph === null) return null;
  if (!Array.isArray(graph.nodes) || !Array.isArray(graph.edges)) return errors.push(`${at}: nodes and edges must be lists`), null;
  const before = errors.length;
  const domains = new Map();
  const flows = new Map();
  for (const n of graph.nodes) {
    if (n.type === "domain") {
      if (!isText(n.name) || !isText(n.summary)) errors.push(`${at}: domain ${n.id} needs a name and a summary`);
      const meta = n.domainMeta ?? {};
      const terms = [...new Set((meta.entities ?? []).filter(isText).map((t) => t.trim()))];
      domains.set(n.id, { name: n.name, summary: n.summary, terms, rules: (meta.businessRules ?? []).filter(isText), flows: [] });
    } else if (n.type === "flow") {
      if (!isText(n.name)) errors.push(`${at}: flow ${n.id} needs a name`);
      flows.set(n.id, { name: n.name, summary: n.summary, entry: n.domainMeta?.entryPoint, owned: false });
    }
  }
  if (domains.size === 0) errors.push(`${at}: has no domains`);
  const names = [...domains.values()].map((d) => d.name);
  for (const n of names) if (names.indexOf(n) !== names.lastIndexOf(n)) errors.push(`${at}: domain name "${n}" is used twice`);
  for (const e of graph.edges) {
    if (e.type !== "contains_flow" || !domains.has(e.source) || !flows.has(e.target)) continue;
    domains.get(e.source).flows.push(flows.get(e.target));
    flows.get(e.target).owned = true;
  }
  if (errors.length > before) return null;
  return { domains: [...domains.values()], orphans: [...flows.values()].filter((f) => !f.owned) };
}

function flowItem(f) {
  const entry = isText(f.entry) ? ` (${code(f.entry)})` : "";
  const summary = isText(f.summary) ? `: ${md(f.summary)}` : "";
  return `- **${md(f.name)}**${entry}${summary}`;
}

// One repo: an A to Z term index that links each term to its domains, then the domains.
// The anchors follow the heading order of the page, as GitHub numbers repeated headings.
function repoGlossary({ name, sha, source }, { domains, orphans }) {
  const slug = slugger();
  for (const h of [`Glossary: ${name}`, "Terms", "Domains"]) slug(h);
  for (const d of domains) d.anchor = slug(d.name);
  const termDomains = new Map();
  for (const d of domains) for (const t of d.terms) termDomains.set(t, [...(termDomains.get(t) ?? []), d]);
  const lines = [
    `# Glossary: ${name}`,
    "",
    `_Generated by \`${SCRIPT}\` from [\`domain-graph.json\`](domain-graph.json) (source commit [\`${sha.slice(0, 7)}\`](${source}/commit/${sha})). Do not edit by hand._`,
    "",
    `This glossary lists the business terms of ${name}. Each term links to its domain, which says what the domain does, its rules, and its flows. The [estate glossary](../../GLOSSARY.md) shows which other repos use the same terms.`,
    "",
    "## Terms",
    "",
    ...[...termDomains.keys()].sort(byName).map((t) => `- **${md(t)}**: ${termDomains.get(t).map((d) => `[${md(d.name)}](#${d.anchor})`).join(", ")}`),
    "",
    "## Domains",
  ];
  for (const d of domains) {
    lines.push("", `### ${md(d.name)}`, "", md(d.summary));
    if (d.terms.length) lines.push("", `**Terms:** ${d.terms.map(md).join(", ")}`);
    if (d.rules.length) lines.push("", "**Rules:**", "", ...d.rules.map((r) => `- ${md(r)}`));
    if (d.flows.length) lines.push("", "**Flows:**", "", ...d.flows.map(flowItem));
  }
  if (orphans.length) lines.push("", "## Other flows", "", "These flows belong to no domain in the graph.", "", ...orphans.map(flowItem));
  return lines.join("\n") + "\n";
}

// The resources of shared-resources.json. The glossary reads only the id and the name of each
// resource; build-shared-resources.mjs checks the rest of the file.
const resources = readSharedResources(errors, "an id and a name", (r) => typeof r.id === "string" && typeof r.name === "string");

// The estate: every term of every repo, A to Z. Terms that differ only in case, spacing,
// punctuation, CamelCase, or a note in parentheses merge into one entry.
const termKey = (t) =>
  t.replace(/\([^)]*\)/g, " ").replace(/([a-z0-9])([A-Z])/g, "$1 $2").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();

// A shared resource is an entry of its own, or it merges with the terms by the same rule.
function estateGlossary(entries, sharedResources) {
  const merged = new Map();
  const entryOf = (term) => {
    const key = termKey(term) || term.toLowerCase();
    const m = merged.get(key) ?? { forms: new Map(), resources: [], uses: [] };
    m.forms.set(term, (m.forms.get(term) ?? 0) + 1);
    merged.set(key, m);
    return m;
  };
  for (const { term, repo, domain } of entries) {
    const m = entryOf(term);
    if (!m.uses.some((u) => u.repo === repo && u.domain === domain)) m.uses.push({ repo, domain });
  }
  for (const r of sharedResources) entryOf(r.name).resources.push(r);
  // The entry of a shared resource shows the name of the resource (the heading of its section).
  // Another entry shows the most used form of the term; a tie goes to the first form A to Z.
  const shown = [...merged.values()].map((m) => ({
    term: m.resources.length ? m.resources[0].name : [...m.forms].sort((a, b) => b[1] - a[1] || byName(a[0], b[0]))[0][0],
    resources: m.resources,
    uses: m.uses.sort((a, b) => byName(a.repo, b.repo) || byName(a.domain.name, b.domain.name)),
  }));
  shown.sort((a, b) => byName(a.term, b.term));
  const letter = (t) => {
    const c = termKey(t).charAt(0).toUpperCase();
    return /\p{L}/u.test(c) ? c : "0-9";
  };
  const groups = new Map();
  for (const s of shown) groups.set(letter(s.term), [...(groups.get(letter(s.term)) ?? []), s]);
  const slug = slugger();
  for (const h of ["Estate glossary"]) slug(h);
  const anchors = new Map([...groups.keys()].map((g) => [g, slug(g)]));
  const lines = [
    "# Estate glossary",
    "",
    `_Generated by \`${SCRIPT}\` from \`repos/*/domain-graph.json\` and \`${SHARED_RESOURCES_DATA}\`. Do not edit by hand._`,
    "",
    `This glossary lists the business terms of all ${count} documented repos and the shared resources of the code repos, A to Z. For each repo that uses a term, the entry links to the domains of the term in the glossary of that repo. For a shared resource, the entry links to its section of the shared-resource page. Terms that differ only in case, spacing, or a note in parentheses are merged.`,
    "",
    `Jump to: ${[...groups.keys()].map((g) => `[${g}](#${anchors.get(g)})`).join(" · ")}`,
  ];
  for (const [g, items] of groups) {
    lines.push("", `## ${g}`, "");
    for (const s of items) {
      // One group per place: "shared resources: [Resource](link)" first, then one group per repo,
      // "repo: [Domain](link), [Domain](link)". The groups are split by " · ".
      const perPlace = new Map();
      if (s.resources.length) perPlace.set("shared resources", s.resources.map((r) => `[${md(r.name)}](${SHARED_RESOURCES_PAGE}#${r.id})`));
      for (const u of s.uses) perPlace.set(u.repo, [...(perPlace.get(u.repo) ?? []), `[${md(u.domain.name)}](repos/${u.repo}/GLOSSARY.md#${u.domain.anchor})`]);
      lines.push(`- **${md(s.term)}**: ${[...perPlace].map(([place, links]) => `${place}: ${links.join(", ")}`).join(" · ")}`);
    }
  }
  return lines.join("\n") + "\n";
}

const outputs = [];
const entries = [];
for (const repo of repos) {
  const graph = readGraph(repo.name);
  if (!graph) continue;
  outputs.push({ path: `repos/${repo.name}/GLOSSARY.md`, text: repoGlossary(repo, graph) });
  for (const domain of graph.domains) for (const term of domain.terms) entries.push({ term, repo: repo.name, domain });
}
if (resources !== null) outputs.push({ path: "GLOSSARY.md", text: estateGlossary(entries, resources) });

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

const stale = outputs.filter((o) => !existsSync(join(root, o.path)) || readFileSync(join(root, o.path), "utf8") !== o.text);
if (check) {
  if (stale.length) {
    for (const o of stale) console.error(`error: ${o.path} is missing or stale`);
    console.error(`Run: node ${SCRIPT}`);
    process.exit(1);
  }
  console.log(`glossaries are current (${repos.length} repos, ${entries.length} term uses)`);
} else {
  for (const o of stale) writeFileSync(join(root, o.path), o.text);
  console.log(`wrote ${stale.length} of ${outputs.length} glossaries (${repos.length} repos, ${entries.length} term uses)`);
}
